    "scene_elements": ["高三教学楼", "监控死角", "透明人状态", "透明层/另一个世界", "失踪三年的学霸", "24小时时间限制", "记忆消失规则"],
    "relationship_tension": ["女主与霸凌者的对立", "女主与男主的错位时空", "看得见却触不到的物理隔阂", "24小时后必须遗忘的残酷规则", "男主三年的孤独等待"],
    "user_preferences": {
      "desired_emotion": "极度虐心、BE美学、悲剧感、无力感",
      "forbidden": ["大团圆结局", "主角光环", "强行救赎", "轻松搞笑"]
